<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';require_once __DIR__.'/pwa_step24.php';$error=null;$catalog=[];try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);foreach(ps23_catalog($pdo,$ctx['organization_id']) as $row)$catalog[(int)$row['id']]=['id'=>(int)$row['id'],'sku'=>$row['sku'],'name'=>$row['product_name'],'mrp'=>(float)$row['mrp'],'vp'=>(float)$row['volume_points'],'availability'=>$row['availability_status']];}catch(Throwable $e){$error=$e->getMessage();}$catalogJson=json_encode($catalog,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);?><!doctype html><html lang="en-IN"><head><?php s24_head('Cart - Healthcare Wellness Club','Review your Healthcare Wellness Club product request cart before checkout.','cart.php','noindex,nofollow,noarchive');?></head><body><a class="skip-link" href="#main-content">Skip to main content</a><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club" width="42" height="42"><span><strong>Healthcare Wellness Club</strong><small>Your Product Cart</small></span></a><nav class="store-actions" aria-label="Cart actions"><a class="store-btn" href="index.php">Continue Shopping</a><a class="store-btn primary" href="checkout.php">Checkout</a></nav></div></header><main class="store-shell" id="main-content"><section class="store-hero" aria-labelledby="cart-title"><div class="store-kicker">ORDER REQUEST CART</div><h1 id="cart-title">Review products before sending your request.</h1><p>Cart totals shown here use current source-listed MRP. The server recalculates every line again during checkout.</p></section><?php if($error):?><div class="notice bad" role="alert"><?=ps23_h($error)?></div><?php endif;?><section class="two-col" style="margin-top:16px"><article class="card"><h2>Products</h2><div id="cartRows" aria-live="polite"></div></article><aside class="card"><h2>Summary</h2><div class="summary-line"><span>MRP Total</span><strong id="sumMrp">₹0.00</strong></div><div class="summary-line"><span>Total VP</span><strong id="sumVp">0</strong></div><div class="notice">Delivery charge is calculated at checkout based on delivery mode and the source-listed VP rule. Taxes are not calculated here.</div><a class="store-btn primary" style="width:100%" href="checkout.php">Continue to Checkout</a><button class="store-btn" style="width:100%;margin-top:8px" id="clearCart" type="button">Clear Cart</button></aside></section></main><footer class="store-footer">No payment is collected at cart stage. <span class="network-badge" data-network-status role="status" aria-live="polite">Online</span></footer><script src="<?=s24_h(s24_asset('store.js'))?>" defer></script><script>
document.addEventListener('DOMContentLoaded',()=>{const catalog=<?=$catalogJson?:'{}'?>;const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(value);const escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));function render(){const cart=hwcCart();const box=document.getElementById('cartRows');box.innerHTML='';let mrp=0,vp=0;if(!cart.length)box.innerHTML='<div class="empty">Your cart is empty. <a href="index.php">Browse products</a></div>';cart.forEach(row=>{const product=catalog[Number(row.product_id)];if(!product)return;const qty=Math.max(1,Math.min(20,Number(row.qty)||1));mrp+=product.mrp*qty;vp+=product.vp*qty;const div=document.createElement('div');div.className='cart-row';const name=escapeHtml(product.name);div.innerHTML=`<div><b>${name}</b><div class="meta">Stock ${escapeHtml(product.sku)} • ${product.availability==='unavailable'?'Unavailable':'MRP '+money(product.mrp)}</div></div><input class="store-input" type="number" min="1" max="20" inputmode="numeric" value="${qty}" data-q="${product.id}" aria-label="Quantity for ${name}"><strong>${money(product.mrp*qty)}</strong><button class="store-btn" type="button" data-r="${product.id}" aria-label="Remove ${name} from cart">×</button>`;box.appendChild(div)});document.getElementById('sumMrp').textContent=money(mrp);document.getElementById('sumVp').textContent=vp.toFixed(3).replace(/0+$/,'').replace(/\.$/,'');box.querySelectorAll('[data-q]').forEach(element=>element.addEventListener('change',()=>{hwcSet(element.dataset.q,element.value);render()}));box.querySelectorAll('[data-r]').forEach(element=>element.addEventListener('click',()=>{hwcRemove(element.dataset.r);hwcAnnounce('Product removed from cart.');render()}));hwcSyncCartBadge()}document.getElementById('clearCart').addEventListener('click',()=>{hwcClear();hwcAnnounce('Cart cleared.');render()});render()});
</script></body></html>
